<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireAuth();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{if(isset($_POST['save_profile'])){$auth->updateProfile(['full_name'=>trim($_POST['full_name']??''),'email'=>trim($_POST['email']??'')]);$msg='Profile updated successfully';}elseif(isset($_POST['change_password'])){$r=$auth->changePassword($_POST['current_password']??'',$_POST['new_password']??'');if($r['success'])$msg=$r['message'];else $err=$r['message'];}}catch(Throwable $e){$err='Unable to update profile';}}$u=$auth->getUserInfo();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profile</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-5" style="max-width:760px"><h2>Profile</h2><?php if($msg):?><div class="alert alert-success"><?=htmlspecialchars($msg)?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=htmlspecialchars($err)?></div><?php endif;?><div class="card mb-4"><div class="card-body"><form method="post"><input type="hidden" name="save_profile" value="1"><label class="form-label">Full name</label><input class="form-control mb-3" name="full_name" value="<?=htmlspecialchars($u['full_name']??'')?>" required><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" value="<?=htmlspecialchars($u['email']??'')?>" required><button class="btn btn-primary">Save profile</button></form></div></div><div class="card"><div class="card-body"><h5>Change password</h5><form method="post"><input type="hidden" name="change_password" value="1"><input class="form-control mb-2" type="password" name="current_password" placeholder="Current password" required><input class="form-control mb-3" type="password" name="new_password" placeholder="New password" minlength="6" required><button class="btn btn-outline-primary">Change password</button></form></div></div></div></body></html>